const menu=document.querySelector('.menu');
const nav=document.querySelector('.nav');
function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Abrir menu');menu.textContent='MENU ☰';}
menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');menu.textContent=open?'FECHAR ×':'MENU ☰';});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){closeMenu();menu.focus();}});
if('IntersectionObserver' in window){document.documentElement.classList.add('js');const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target);}}),{threshold:.07});document.querySelectorAll('.reveal').forEach(el=>io.observe(el));}
const progress=document.querySelector('.progress');let scheduled=false;function updateProgress(){const max=document.documentElement.scrollHeight-innerHeight;progress.style.width=(max>0?Math.min(100,scrollY/max*100):0)+'%';scheduled=false;}addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(updateProgress);}}, {passive:true});updateProgress();
function buildContactUrl(interest,name){const course=interest==='presencial';const subject=course?'informações sobre o curso presencial':interest==='visagismo'?'saber mais sobre o atendimento de visagismo':'agendar um atendimento';const cleanName=name.trim().slice(0,70);const text=`Olá! ${cleanName?'Meu nome é '+cleanName+'. ':''}Gostaria de ${subject}.`;return 'https://api.whatsapp.com/send?phone='+(course?'5527999719694':'5527999719690')+'&text='+encodeURIComponent(text);}
document.querySelector('#booking-form').addEventListener('submit',e=>{e.preventDefault();const interest=document.querySelector('#interest').value;const name=document.querySelector('#name').value;window.location.assign(buildContactUrl(interest,name));});
